const $=s=>document.querySelector(s);
const STORE='missao-web-v1';
let saved={};try{saved=JSON.parse(localStorage.getItem(STORE)||'{}')||{};}catch{}
let state={drafts:saved.drafts||{},done:saved.done||{},hints:saved.hints||{},supported:saved.supported||{},last:Number.isInteger(saved.last)?saved.last:0};
let current=0,token='',testing=false,timer,refreshTimer;
const escapeHTML=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{$('#feedback').textContent='O armazenamento está indisponível. Exporta o progresso antes de fechar.';}}
function renderMap(){
 let total=challenges.filter(c=>state.done[c.id]).length;
 $('#xp').textContent=total*100;$('#count').textContent=total+' / '+challenges.length;$('#progressBar').style.width=(total/challenges.length*100)+'%';
 $('#schoolStatus').textContent=total===16?'Escola reconstruída. Missão cumprida!':total?total+' desafios recuperados. Continua a construir!':'À espera do teu primeiro código';
 $('#continueBtn').innerHTML=total===16?'Revisitar a escola <span>↗</span>':Object.keys(state.drafts).length?'Continuar a aventura <span>↗</span>':'Começar a aventura <span>↗</span>';
 $('#missions').innerHTML=missions.map((m,i)=>{let items=challenges.filter(c=>c.m===i),done=items.filter(c=>state.done[c.id]).length;return `<button class="mission ${done===items.length?'completed':''}" style="--tint:${m.color}" data-mission="${i}"><span class="num">0${i+1}</span><span class="icon" aria-hidden="true">${m.icon}</span><h3>${m.name}</h3><p>${m.desc}</p><span class="pill">${m.topic}</span><span class="mission-foot"><span>${done===items.length?'✓ Concluída':done+' / '+items.length+' desafios'}</span><span>↗</span></span></button>`}).join('');
 document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{let list=challenges.filter(c=>c.m===Number(b.dataset.mission));openChallenge((list.find(c=>!state.done[c.id])||list[0]).id)});
}
function showMap(){saveDraft();document.body.classList.remove('playing');$('#workspace').hidden=true;renderMap();window.scrollTo({top:0,behavior:'smooth'});}
function saveDraft(){if(document.body.classList.contains('playing')){state.drafts[current]=$('#editor').value;persist();}}
function openChallenge(id){saveDraft();current=Math.max(0,Math.min(challenges.length-1,id));state.last=current;persist();const c=challenges[current],m=missions[c.m];document.body.classList.add('playing');$('#workspace').hidden=false;$('#missionTag').textContent=m.topic+' / MISSÃO 0'+(c.m+1);$('#challengeTitle').textContent=c.title;$('#story').textContent=m.desc;$('#objective').textContent=c.objective;$('#lesson').innerHTML=c.lesson;$('#codeLanguage').textContent=c.mode==='html'?'index.html':c.mode==='css'?'style.css':'script.js';$('#editor').value=state.drafts[c.id]??c.start;$('#hint').textContent='';$('#hintCount').textContent='';$('#nextBtn').hidden=!state.done[c.id];$('#levelLabel').textContent='DESAFIO '+(current+1)+' DE '+challenges.length;$('#viewport').value='100%';$('#preview').style.width='100%';$('#feedback').className='';$('#feedback').textContent=state.done[c.id]?'✓ Já concluíste este desafio. Podes continuar a experimentar.':'O teu laboratório está pronto. Altera o código e testa a tua ideia.';$('#levelNav').innerHTML=challenges.filter(x=>x.m===c.m).map(x=>`<button data-level="${x.id}" class="${x.id===c.id?'current':''}">${state.done[x.id]?'✓ ':''}${x.title.split(' / ')[0]} ${x.id===15?'Projeto final':''}</button>`).join('');document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>openChallenge(+b.dataset.level));renderControls(c);run(false);window.scrollTo({top:0,behavior:'smooth'});}
function renderControls(c){document.querySelector('details').open=false;const el=$('#explore');el.innerHTML='';if(!c.controls)return;
 if(c.controls.type==='title'){el.innerHTML='<label>Explorar a hierarquia <select id="titleControl"><option>h1</option><option>h2</option><option>h3</option></select></label>';$('#titleControl').onchange=e=>{$('#editor').value=$('#editor').value.replace(/<(\/?)(h[123])>/g,`<$1${e.target.value}>`);edited();};}
 if(c.controls.type==='flex'){el.innerHTML='<label>Distribuição <select id="flexControl"><option>flex-start</option><option>center</option><option>flex-end</option><option>space-between</option></select></label><label>Intervalo <select id="gapControl"><option value="0">0 px</option><option value="10">10 px</option><option value="20">20 px</option><option value="40">40 px</option></select></label>';$('#flexControl').onchange=e=>{$('#editor').value=$('#editor').value.replace(/justify-content:\s*[^;]+;/,`justify-content: ${e.target.value};`);edited();};$('#gapControl').onchange=e=>{$('#editor').value=$('#editor').value.replace(/gap:\s*[^;]+;/,`gap: ${e.target.value}px;`);edited();};}
 if(c.controls.type==='grid'){el.innerHTML='<label>Colunas <select id="columnsControl"><option>1</option><option>2</option><option>3</option><option>4</option></select></label>';$('#columnsControl').onchange=e=>{$('#editor').value=$('#editor').value.replace(/grid-template-columns:\s*[^;]+;/,`grid-template-columns: repeat(${e.target.value}, 1fr);`);edited();};}
}
function edited(){saveDraft();clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>run(false),650);}
const previewCSS=`*{box-sizing:border-box}body{font:14px/1.5 system-ui;color:#213e32;padding:16px;margin:0;background:#fffef9}h1{font-size:27px;line-height:1.2}h2{font-size:21px}a{color:#28624a}nav a{font-size:11px}nav b{font-size:12px}header,footer{padding:12px;background:#e9efda;border-radius:6px}main{padding:12px 0}img{max-width:100%;height:auto}label{display:block;font-size:12px;margin:12px 0}input{width:100%;padding:9px;border:1px solid #b8c9aa;border-radius:5px;display:block;font:inherit;background:white}button{background:#285e49;color:white;border:0;border-radius:5px;padding:10px 15px;cursor:pointer}output{font-weight:bold}.cartao{background:#e7eed8;border:1px solid #c6d5b5;border-radius:6px;padding:16px 8px;text-align:center;font-size:12px}.equipa{min-height:150px;background:#f0f3e7;padding:10px;border-radius:8px}.equipa>span{font-size:35px;background:#e1e9cc;border-radius:8px;padding:8px}.menu{background:#e9efdb;padding:12px;border-radius:8px}form{max-width:400px}#mensagem{font-weight:600}`;
function scriptTag(s){return '<script>'+s.replace(/<\/script/gi,'<\\/script')+'<\/script>';}
function helpers(){
 window.shopCase=(n,expected)=>{let q=document.querySelector('#quantidade'),t=document.querySelector('#total');q.value=n;document.querySelector('#calcular').click();return t.textContent.trim()!==''&&Math.abs(Number(t.textContent.replace(',','.'))-expected)<.001;};
 window.formCase=(name,email,expected)=>{document.querySelector('#nome').value=name;document.querySelector('#email').value=email;let e=new Event('submit',{bubbles:true,cancelable:true});document.querySelector('form').dispatchEvent(e);return e.defaultPrevented&&document.querySelector('#mensagem').textContent.trim()===expected;};
 window.reserveCase=(n,valid,cost)=>{document.querySelector('#participantes').value=n;let e=new Event('submit',{bubbles:true,cancelable:true});document.querySelector('form').dispatchEvent(e);let t=document.querySelector('#custo').textContent.trim();return e.defaultPrevented&&document.querySelector('#mensagem').textContent.trim()===(valid?'Reserva confirmada':'Número inválido')&&(valid?t!==''&&Number(t.replace(',','.'))===cost:t==='');};
 window.responsiveGrid=async()=>{let style=[...document.querySelectorAll('style')].map(s=>s.textContent).join('\n'),html=document.querySelector('.mural').outerHTML;async function columns(width){let f=document.createElement('iframe');f.style.cssText='position:absolute;left:-9999px;width:'+width+'px;height:300px;border:0';document.body.appendChild(f);let value=await new Promise(resolve=>{let timeout;const listen=e=>{if(e.source===f.contentWindow&&e.data?.type==='grid-width'){clearTimeout(timeout);window.removeEventListener('message',listen);resolve(e.data.columns);}};window.addEventListener('message',listen);timeout=setTimeout(()=>{window.removeEventListener('message',listen);resolve(0);},1500);f.srcdoc='<style>'+style+'</style>'+html+'<script>parent.postMessage({type:"grid-width",columns:getComputedStyle(document.querySelector(".mural")).gridTemplateColumns.split(" ").length},"*")<'+'/script>';});f.remove();return value;}return await columns(320)===1&&await columns(480)===2;};
}
function makeDocument(c,code,test,nonce){let content=c.mode==='html'?code:c.html;let styles=previewCSS+(c.mode==='css'?'\n'+code:'');let hook='';
 if(c.id===9)hook=`document.querySelector('#calcular').addEventListener('click',()=>{try{document.querySelector('#total').textContent=calcularTotal(2.5,Number(document.querySelector('#quantidade').value));}catch(e){document.querySelector('#total').textContent=e.message;}});`;
 if(c.id===10)hook=`document.querySelector('#desconto').addEventListener('click',()=>{try{document.querySelector('#final').textContent=calcularDesconto(Number(document.querySelector('#valor').value),Number(document.querySelector('#percentagem').value));}catch(e){document.querySelector('#final').textContent=e.message;}});`;
 const tests=JSON.stringify(c.tests).replace(/</g,'\\u003c');
 let runner=`window.addEventListener('load',async()=>{${test?`const results=[];for(const t of ${tests}){try{results.push({label:t.label,pass:!!(await (new Function('return ('+t.expr+')'))())});}catch(e){results.push({label:t.label,pass:false,error:e.message});}}parent.postMessage({type:'mission-result',token:${JSON.stringify(nonce)},results},'*');`:`parent.postMessage({type:'preview-ready',token:${JSON.stringify(nonce)}},'*');`}});`;
 let error=`window.addEventListener('error',e=>parent.postMessage({type:'preview-error',token:${JSON.stringify(nonce)},message:e.message},'*'));document.addEventListener('click',e=>{if(e.target.closest('a'))e.preventDefault()});document.addEventListener('submit',e=>{if(!${[13,14,15].includes(c.id)})e.preventDefault()});`;
 return '<!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><base href="'+location.href.split('#')[0]+'"><style>'+styles+'</style>'+scriptTag(error)+'</head><body>'+content+scriptTag('('+helpers.toString()+')();')+(c.mode==='js'?scriptTag(code):'')+scriptTag(hook)+scriptTag(runner)+'</body></html>';
}
function setTesting(v){testing=v;$('#testBtn').disabled=v;$('#testBtn').textContent=v?'A testar…':'Testar código →';}
function run(test){clearTimeout(timer);clearTimeout(refreshTimer);saveDraft();token=crypto.randomUUID();setTesting(test);if(test){$('#feedback').className='';$('#feedback').textContent='A verificar o comportamento do teu código…';timer=setTimeout(()=>{setTesting(false);$('#feedback').className='fail';$('#feedback').textContent='O teste não terminou. Confirma se há erros ou um ciclo que não termina e volta a testar.';},7000);}$('#preview').srcdoc=makeDocument(challenges[current],$('#editor').value,test,token);}
window.addEventListener('message',e=>{if(e.source!==$('#preview').contentWindow||e.data?.token!==token)return;let d=e.data;if(d.type==='preview-error'){clearTimeout(timer);setTesting(false);$('#feedback').className='fail';$('#feedback').textContent='O navegador encontrou um erro: '+d.message;return;}if(d.type!=='mission-result')return;clearTimeout(timer);setTesting(false);const pass=d.results.every(r=>r.pass);$('#feedback').className=pass?'success':'fail';$('#feedback').innerHTML=(pass?'<b>✓ Missão cumprida! +100 XP</b>':'<b>Ainda falta um passo. Continua a experimentar.</b>')+'<ul>'+d.results.map(r=>'<li>'+ (r.pass?'✓ ':'○ ')+escapeHTML(r.label)+(r.error?' <small>('+escapeHTML(r.error)+')</small>':'')+'</li>').join('')+'</ul>';if(pass){if(state.done[current])$('#feedback b').textContent='✓ Resultado confirmado. Desafio já concluído.';state.done[current]={date:new Date().toISOString()};persist();$('#nextBtn').hidden=false;$('#nextBtn').textContent=current===15?'Ver a escola reconstruída ✦':'Próximo desafio →';renderMap();$('#levelNav button.current').textContent='✓ '+challenges[current].title.split(' / ')[0];}});
$('#editor').addEventListener('input',edited);$('#editor').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();let t=e.target,s=t.selectionStart,end=t.selectionEnd;t.setRangeText('  ',s,end,'end');edited();}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run(true);}});
$('#testBtn').onclick=()=>run(true);$('#previewBtn').onclick=()=>run(false);$('#backBtn').onclick=showMap;$('#mapBtn').onclick=showMap;$('.brand').onclick=e=>{e.preventDefault();showMap();};$('#continueBtn').onclick=()=>openChallenge(state.last||0);$('#nextBtn').onclick=()=>current===15?showMap():openChallenge(current+1);
$('#viewport').onchange=e=>{$('#preview').style.width=e.target.value;};
$('#resetBtn').onclick=()=>{if(confirm('Repor o código inicial deste desafio?')){$('#editor').value=challenges[current].start;edited();}};
$('#hintBtn').onclick=()=>{let c=challenges[current],n=state.hints[current]||0;$('#hint').textContent=c.hints[Math.min(n,c.hints.length-1)];state.hints[current]=Math.min(n+1,c.hints.length);$('#hintCount').textContent='('+state.hints[current]+'/'+c.hints.length+')';persist();};
$('#solutionBtn').onclick=()=>{state.supported[current]=true;$('#editor').value=challenges[current].solution;edited();$('#hint').textContent='Solução consultada. Testa-a e explica por palavras tuas o que faz cada parte.';};
$('#guideBtn').onclick=()=>$('#guide').showModal();$('#guide .close').onclick=()=>$('#guide').close();$('#guide').onclick=e=>{if(e.target===$('#guide'))$('#guide').close();};
function exportReport(){saveDraft();let done=challenges.filter(c=>state.done[c.id]).length;let txt='MISSÃO WEB — RELATÓRIO DO PERCURSO\n'+new Date().toLocaleString('pt-PT')+'\n\n'+done+'/'+challenges.length+' desafios | '+done*100+' XP\nProgresso local deste navegador.\n\n';for(const c of challenges){txt+=missions[c.m].name+' — '+c.title+'\nEstado: '+(state.done[c.id]?'Concluído':'Por concluir')+' | Pistas: '+(state.hints[c.id]||0)+' | Solução consultada: '+(state.supported[c.id]?'Sim':'Não')+'\nObjetivo: '+c.objective+'\nCódigo atual:\n'+(state.drafts[c.id]??c.start)+'\n\n';}txt+='Reflexão: Que conceitos consegui aplicar? O que mudaria numa nova versão?\n';let a=document.createElement('a'),u=URL.createObjectURL(new Blob([txt],{type:'text/plain;charset=utf-8'}));a.href=u;a.download='missao-web-percurso.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('#exportBtn').onclick=exportReport;$('#downloadGuide').onclick=exportReport;
$('#clearBtn').onclick=()=>{if(confirm('Limpar todo o código e progresso guardados neste navegador? Esta ação não pode ser desfeita.')){state={drafts:{},done:{},hints:{},supported:{},last:0};persist();document.body.classList.remove('playing');$('#workspace').hidden=true;renderMap();}};
renderMap();
